import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Definizione di Poliedro","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/gh/ghda.md","filePath":"lezioni/g_geometria-dello-spazio/gh/ghda.md"}`),a={name:`lezioni/g_geometria-dello-spazio/gh/ghda.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="definizione-di-poliedro" tabindex="-1">Definizione di Poliedro <a class="header-anchor" href="#definizione-di-poliedro" aria-label="Permalink to “Definizione di Poliedro”">​</a></h1><blockquote><p><strong>Definizione:</strong> <strong>Poliedro</strong> è la parte di spazio limitata da un numero finito di poligoni, giacenti su piani diversi ed aventi, due a due, un lato in comune.</p><p>Poliedro deriva dal greco <em>poli</em> (più) ed <em>edros</em> (facce), quindi letteralmente significa più facce.</p></blockquote><p>Ogni poligono si chiama <strong>Faccia</strong> L&#39;insieme delle facce si chiama <strong>Superficie poliedrica</strong> La parte di spazio limitata dalla superficie poliedrica si chiama <strong>Volume</strong> del poliedro I lati dei poligoni si chiamano <strong>Spigoli</strong> del poliedro I vertici dei poligoni si chiamano <strong>Vertici</strong> del poliedro</p><p>Il tipo di poliedro è individuato dal numero di facce della superficie poliedrica:</p><ul><li><strong>Tetraedro</strong>: poliedro con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> facce</li><li><strong>Pentaedro</strong>: poliedro con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn></mrow><annotation encoding="application/x-tex">5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> facce</li><li><strong>Esaedro</strong>: poliedro con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>6</mn></mrow><annotation encoding="application/x-tex">6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> facce</li><li><strong>Icosaedro</strong>: poliedro con <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>20</mn></mrow><annotation encoding="application/x-tex">20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">20</span></span></span></span> facce</li></ul><blockquote><p><strong>Nota:</strong> A lato un esaedro. I lati nascosti dietro la figura sono tratteggiati.</p></blockquote>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};